#include "game_root.h"
#include "sub_hover.h"
#include "player.h"
#include "subgame_runtime.h"
#include "track_attachment_types.h"
#include "vector3.h"


float Cos(float angle);
float Sin(float angle);
int debug_report_stub(char* format, ...);

void cRSubHover::AI()
{
    int zero = 0;

    int live_state = state;
    live_state -= zero;
    if (!live_state)
        return;
    switch (live_state) {
    case SUB_HOVER_STATE_ACTIVE:
        break;
    default:
        return;
    }

    {
        float next_progress = progress + progress_step;
        progress = next_progress;

        cRSubGame* live_game = game;
        cRSubGoldy* live_player = player;
        if (next_progress > 1.0f
            || (float)(live_game->completion_row_start - 5) < live_player->transform.position.z) {
            goto finish_hover;
        }

        if (next_progress < 0.100000001f) {
            warning_intensity = next_progress * 10.0f;
        } else if (next_progress > 0.94f) {
            warning_intensity = (1.0f - next_progress) * 16.6666679f;
            if (next_progress - progress_step <= 0.94f) {
                g_game->subgame.embedded_player()->presentation.SetJetPack(0);
                JetUnInit();
            }
        } else {
            warning_intensity = 1.0f;
            SubRow* runtime_cell =
                g_game->subgame.RowFromPos(
                    &g_game->subgame.embedded_player()->transform.position);
            if ((runtime_cell->flags & SUBROW_FLAG_JETPACK_OFF) != 0) {
                progress = 0.94f;
                debug_report_stub("Auto Shutoff Jetpack\n");
            }
        }

        warning_intensity =
            1.0f - (Cos(warning_intensity * 3.1415927f) + 1.0f) * 0.5f;
        wobble_x = Sin(progress * 25.132742f) * warning_intensity * 0.25f;
        float wobble_y_sine = Sin(progress * 37.699112f);
        int intensity_bits = *(int*)&warning_intensity;
        wobble_alpha = 0.0f;
        *(int*)&warning_intensity_latch = intensity_bits;
        wobble_y = (wobble_y_sine * 0.25f + 1.0f) * warning_intensity;
        Hover(player->transform.position, progress);
        return;
    }

finish_hover:
    End();
    if (progress <= 0.94f)
        g_game->subgame.embedded_player()->presentation.SetJetPack(0);
    state = SUB_HOVER_STATE_INACTIVE;
    wobble_alpha = (float)zero;
    wobble_y = (float)zero;
    wobble_x = (float)zero;
}

